          "url": "https://uscode.house.gov/view.xhtml?edition=prelim&num=0&req=granuleid%3AUSC-prelim-title8-section1324",
          "captureDate": "2026-07-30",
          "supportingExcerpt": "§ 1324. Bringing in and harboring certain aliens",
          "unlockGroupId": null
