              "locator": "8 U.S.C. 1360 > Editorial Notes",
              "url": "https://uscode.house.gov/view.xhtml?edition=prelim&num=0&req=granuleid%3AUSC-prelim-title8-section1360",
              "captureDate": "2026-07-30",
