          "locator": "8 U.S.C. 1809",
          "url": "https://uscode.house.gov/view.xhtml?edition=prelim&num=0&req=granuleid%3AUSC-prelim-title8-section1809",
          "captureDate": "2026-07-30",
          "supportingExcerpt": "§ 1809. Fee relating to renewal and extension of employment authorization for parolees",
          "unlockGroupId": null
