          "url": "https://uscode.house.gov/view.xhtml?edition=prelim&num=0&req=granuleid%3AUSC-prelim-title8-section1811",
          "captureDate": "2026-07-30",
          "supportingExcerpt": "§ 1811. Fee relating to renewal and extension of employment authorization for aliens granted temporary protected status",
          "unlockGroupId": null
